    raytrace_openmp(c->width, c->height, c->baseWidth, c->baseHeight, c->raster2camera, c->camera2world, image, ids,
                    (const ispc::LinearBVHNode *)c->nodes, (const ispc::Triangle *)c->triangles, threads);
}

