static inline void raytrace_row(int y, int width, float widthScale, float heightScale,
                                const float raster2camera[4][4], const float camera2world[4][4],
                                float image[], int id[], const LinearBVHNode nodes[], const Triangle triangles[]) {
    for (int x = 0; x < width; ++x) {
        Ray ray;
        generateRay(raster2camera, camera2world, x * widthScale, y * heightScale, ray);
        BVHIntersect(nodes, triangles, ray);

        int offset = y * width + x;
        image[offset] = ray.maxt;
        id[offset] = ray.hitId;
    }
}

void raytrace_serial(int width, int height, int baseWidth, int baseHeight, const float raster2camera[4][4],
                     const float camera2world[4][4], float image[], int id[], const LinearBVHNode nodes[],
                     const Triangle triangles[]) {
    float widthScale = float(baseWidth) / float(width);
    float heightScale = float(baseHeight) / float(height);

    for (int y = 0; y < height; ++y)
        raytrace_row(y, width, widthScale, heightScale, raster2camera, camera2world, image, id, nodes, triangles);
}

void raytrace_openmp(int width, int height, int baseWidth, int baseHeight, const float raster2camera[4][4],
                     const float camera2world[4][4], float image[], int id[], const LinearBVHNode nodes[],
                     const Triangle triangles[], int threads) {
    const int teamSize = std::min(threads, height);
    if (teamSize <= 1) {
        raytrace_serial(width, height, baseWidth, baseHeight, raster2camera, camera2world, image, id, nodes,
                        triangles);
        return;
    }

    float widthScale = float(baseWidth) / float(width);
    float heightScale = float(baseHeight) / float(height);

    if (teamSize <= 4) {
#pragma omp parallel for num_threads(teamSize) schedule(static)
        for (int y = 0; y < height; ++y)
            raytrace_row(y, width, widthScale, heightScale, raster2camera, camera2world, image, id, nodes,
                         triangles);
    } else {
#pragma omp parallel for num_threads(teamSize) schedule(dynamic, 4)
        for (int y = 0; y < height; ++y)
            raytrace_row(y, width, widthScale, heightScale, raster2camera, camera2world, image, id, nodes,
                         triangles);
    }
}

